    <link href="https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/font/bootstrap-icons.css" rel="stylesheet">
    <script src="https://unpkg.com/html5-qrcode@2.3.8/html5-qrcode.min.js"></script>
    <style>
        :root{--primary:#205bd7;--ink:#18243d;--muted:#7c8ba3;--line:#e8edf5;--surface:#fff;--bg:#f4f7fb;--success:#24a56a;--warning:#eaa52c;--danger:#d84c61}
        *{box-sizing:border-box}body{margin:0;background:linear-gradient(145deg,#edf3fb 0%,#f8faff 48%,#e9f1fc 100%);color:var(--ink);font-family:Inter,ui-sans-serif,system-ui,-apple-system,"Segoe UI",sans-serif;min-height:100vh}
        body:before{content:"";position:fixed;inset:0;pointer-events:none;opacity:.035;background-image:radial-gradient(#234b88 1px,transparent 1px);background-size:22px 22px}
        .shell{width:min(1440px,100%);margin:auto;padding:14px;position:relative}.card{background:#fff;border:1px solid rgba(232,237,245,.92);border-radius:18px;box-shadow:0 12px 34px rgba(7,24,54,.16)}
        .topbar{min-height:82px;padding:14px 18px;display:flex;align-items:center;justify-content:space-between;gap:18px}.brand{display:flex;align-items:center;gap:13px;min-width:0}.logo{width:50px;height:50px;border-radius:14px;background:linear-gradient(135deg,#316ee8,#153caa);color:#fff;display:grid;place-items:center;flex:none;box-shadow:0 7px 18px #205bd736}.logo img{width:100%;height:100%;object-fit:contain;border-radius:14px;background:#fff;padding:6px}.brand-text{min-width:0}.brand strong{display:block;font-size:1.05rem;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.brand small{color:var(--muted);display:block;margin-top:3px}.online{color:var(--success);font-weight:700}.top-actions{display:flex;align-items:center;gap:18px}.clock{text-align:right}.clock strong{display:block;font-size:1.55rem;line-height:1;color:#193e91;letter-spacing:.04em}.clock small{display:block;color:var(--muted);margin-top:6px;font-size:.72rem}.exit{height:44px;padding:0 17px;border:1px solid var(--line);border-radius:12px;background:#fff;color:var(--ink);font-weight:700;text-decoration:none;display:flex;align-items:center;gap:8px}
        .stats{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin:14px 0}.stat{padding:17px 18px;display:flex;align-items:center;gap:14px}.stat-icon{width:44px;height:44px;border-radius:13px;display:grid;place-items:center;font-size:1.15rem}.stat:nth-child(1) .stat-icon{background:#eaf0ff;color:var(--primary)}.stat:nth-child(2) .stat-icon{background:#e7f8ef;color:var(--success)}.stat:nth-child(3) .stat-icon{background:#fff3dd;color:var(--warning)}.stat strong{font-size:1.35rem;display:block;line-height:1}.stat span{font-size:.75rem;color:var(--muted);display:block;margin-top:6px}
        .workspace{display:grid;grid-template-columns:minmax(360px,.92fr) minmax(420px,1.08fr);gap:14px}.panel{min-height:560px;overflow:hidden}.panel-head{height:55px;padding:0 18px;border-bottom:1px solid var(--line);display:flex;align-items:center;justify-content:space-between;font-size:.78rem;font-weight:800;letter-spacing:.08em}.panel-head i{color:var(--primary);margin-right:7px}.camera-state{border:0;font:inherit;font-size:.68rem;letter-spacing:0;color:var(--success);background:#e8f8ef;padding:7px 11px;border-radius:99px;cursor:pointer;font-weight:800}.camera-state.off{color:#b36b00;background:#fff3dd}.camera-wrap{padding:18px}.camera-stage{background:#fff;border-radius:15px;overflow:hidden;min-height:425px;display:grid;place-items:center;position:relative}#reader{width:100%;border:0!important;color:#8090a7} .camera-stage.active{background:#101826;color:#fff}.camera-placeholder{min-height:300px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:9px;text-align:center}.camera-placeholder i{font-size:3rem;color:#17243a}.camera-placeholder strong{font-size:.82rem;color:#34445e}.request-camera{border:0;border-radius:8px;background:#2362d5;color:#fff;padding:9px 14px;font-size:.7rem;font-weight:750;box-shadow:0 5px 12px #2362d533}.request-camera:hover{background:#174daf}.camera-placeholder small{font-size:.7rem;color:#8b98ab}.image-scan-link{font-size:.7rem;color:#2362d5;text-decoration:underline;cursor:pointer}#reader video{width:100%!important;max-height:425px;object-fit:cover;border-radius:14px}#reader__dashboard_section_csr button,#reader__dashboard_section_swaplink{border:0;border-radius:9px;padding:9px 12px;background:#fff;color:#18376d;font-weight:700}.scan-guide{display:flex;justify-content:center;align-items:center;gap:7px;color:var(--muted);font-size:.74rem;margin-top:13px}
        .result-body{height:505px;padding:30px;display:grid;place-items:center;text-align:center}.result-empty i{font-size:3rem;color:#c4cee0}.result-empty h2{font-size:1.05rem;margin:14px 0 6px}.result-empty p{color:var(--muted);font-size:.82rem;margin:0}.student-avatar{width:96px;height:96px;border-radius:25px;margin:0 auto 20px;background:linear-gradient(145deg,#e9efff,#d9e5ff);color:var(--primary);display:grid;place-items:center;font-size:2.25rem;font-weight:800;border:6px solid #f5f8ff}.result-card h2{font-size:1.5rem;margin:0 0 7px}.student-meta{color:var(--muted);font-size:.84rem}.result-badge{display:inline-flex;align-items:center;gap:7px;margin-top:22px;padding:10px 14px;border-radius:10px;font-size:.78rem;font-weight:750}.success .student-avatar{background:#e1f7ea;color:var(--success)}.success .result-badge{background:#e8f8ef;color:#188252}.error .student-avatar{background:#fff0f2;color:var(--danger)}.error .result-badge{background:#fff0f2;color:#ba354d}.pulse{animation:pulse .38s ease}@keyframes pulse{50%{transform:scale(.97);opacity:.75}}
        .activity{margin-top:14px;padding:17px 18px}.activity h3{font-size:.85rem;margin:0 0 12px}.activity-list{display:flex;gap:10px;overflow:auto}.activity-item{border:1px solid var(--line);border-radius:12px;padding:11px 13px;min-width:205px}.activity-item strong{display:block;font-size:.8rem}.activity-item small{display:block;color:var(--muted);font-size:.7rem;margin-top:4px}.empty-activity{color:var(--muted);font-size:.75rem}
        .scan-popup{position:fixed;inset:0;z-index:9999;background:rgba(12,22,40,.62);padding:18px;display:grid;place-items:center;opacity:0;visibility:hidden;transition:.2s}.scan-popup.show{opacity:1;visibility:visible}.scan-popup-card{width:min(390px,100%);background:#fff;border-radius:24px;padding:25px 22px 20px;text-align:center;box-shadow:0 24px 70px rgba(0,0,0,.3);transform:scale(.92);transition:.2s}.scan-popup.show .scan-popup-card{transform:scale(1)}.popup-icon{width:70px;height:70px;border-radius:50%;margin:0 auto 14px;display:grid;place-items:center;font-size:2rem}.scan-popup.success .popup-icon{color:#148652;background:#e5f8ed}.scan-popup.warning .popup-icon{color:#b46b00;background:#fff2d8}.scan-popup.error .popup-icon{color:#c5344c;background:#ffebef}.scan-popup h2{font-size:1.25rem;margin:0 0 7px}.scan-popup-message{color:var(--muted);font-size:.8rem;margin:0 0 14px}.popup-details{border-radius:14px;background:#f5f7fb;padding:5px 14px;margin-bottom:17px;text-align:left}.popup-row{display:flex;justify-content:space-between;gap:14px;padding:9px 0;border-bottom:1px solid #e5eaf2;font-size:.78rem}.popup-row:last-child{border:0}.popup-row span{color:var(--muted)}.popup-row strong{text-align:right}.popup-close{width:100%;border:0;border-radius:11px;padding:11px;background:var(--primary);color:#fff;font-weight:800;cursor:pointer}
        @media(max-width:860px){.shell{padding:12px}.workspace{grid-template-columns:1fr}.panel{min-height:auto}.result-body{height:auto;min-height:390px}.camera-stage{min-height:340px}.topbar{min-height:72px}.clock small{display:none}.workspace .result-panel{order:2}}
        @media(max-width:560px){.shell{padding:7px}.card{border-radius:15px}.topbar{padding:10px 11px}.logo{width:43px;height:43px}.brand strong{font-size:.88rem}.brand small{font-size:.66rem}.top-actions{gap:8px}.clock strong{font-size:1.05rem}.exit{width:42px;padding:0;justify-content:center}.exit span{display:none}.stats{gap:7px;margin:9px 0}.stat{padding:12px 9px;gap:8px}.stat-icon{width:35px;height:35px;border-radius:10px}.stat strong{font-size:1.05rem}.stat span{font-size:.62rem}.panel-head{padding:0 14px}.camera-wrap{padding:10px}.camera-stage{min-height:326px}.result-body{min-height:365px;padding:22px 15px}.student-avatar{width:78px;height:78px;border-radius:21px;font-size:1.8rem}.result-card h2{font-size:1.2rem}.activity{margin-top:9px}}
        .camera-actions{display:flex;align-items:center;gap:7px}.camera-select{max-width:150px;border:1px solid var(--line);border-radius:9px;background:#fff;color:var(--ink);padding:7px 9px;font:inherit;font-size:.68rem;letter-spacing:0;font-weight:700}@media(max-width:560px){.panel-head{height:auto;min-height:55px;padding-top:8px;padding-bottom:8px;gap:8px}.camera-select{max-width:130px}}
    </style>
</head>
<body>
<main class="shell">
    <header class="card topbar">
        <div class="brand"><div class="logo">@if($school?->school_logo)<img src="{{asset('storage/'.$school->school_logo)}}" alt="Logo">@else<i class="bi bi-qr-code"></i>@endif</div><div class="brand-text"><strong>{{$school?->school_name ?: 'Sistem Absensi Siswa'}}</strong><small><span class="online">ONLINE</span> Mode Scan Absensi{{$class?->class_name ? ' - Kelas '.$class->class_name : ''}}</small></div></div>
        <div class="top-actions"><div class="clock"><strong id="clock">--:--:--</strong><small>{{now()->translatedFormat('l, d F Y')}}</small></div><a class="exit" href="{{route('dashboard')}}"><i class="bi bi-box-arrow-right"></i><span>Keluar Mode</span></a></div>
    </header>
    <section class="stats">
        <div class="card stat"><div class="stat-icon"><i class="bi bi-clipboard2-check"></i></div><div><strong id="total">{{$today}}</strong><span>Total Tercatat</span></div></div>
        <div class="card stat"><div class="stat-icon"><i class="bi bi-check-circle"></i></div><div><strong id="present">{{$present}}</strong><span>Hadir</span></div></div>
        <div class="card stat"><div class="stat-icon"><i class="bi bi-clock"></i></div><div><strong id="late">{{$late}}</strong><span>Terlambat</span></div></div>
    </section>
    <section class="workspace">
        <article class="card panel"><div class="panel-head"><span><i class="bi bi-qr-code-scan"></i>PEMINDAI QR</span><div class="camera-actions"><select id="cameraFacing" class="camera-select" aria-label="Pilih kamera"><option value="environment" selected>Kamera Belakang</option><option value="user">Kamera Depan</option></select><button type="button" class="camera-state" id="toggleScanner">MULAI SCAN</button></div></div><div class="camera-wrap"><div class="camera-stage"><div id="reader"><div class="camera-placeholder"><i class="bi bi-phone"></i><strong>Siap memindai kartu siswa</strong><button type="button" class="request-camera" onclick="document.getElementById('toggleScanner').click()">Izinkan Kamera</button><label class="image-scan-link" for="qrImageInput">Scan dari gambar</label></div></div></div><input id="qrImageInput" type="file" accept="image/*" hidden><div class="scan-guide"><i class="bi bi-info-circle"></i> Arahkan QR kartu pelajar ke kamera</div></div></article>
        <article class="card panel result-panel"><div class="panel-head"><span><i class="bi bi-stars"></i>HASIL PRESENSI</span></div><div class="result-body" id="resultBody"><div class="result-empty"><i class="bi bi-person-bounding-box"></i><h2>Menunggu pemindaian</h2><p>Data siswa akan muncul otomatis setelah QR terbaca.</p></div></div></article>
    </section>
    <section class="card activity"><h3>Aktivitas Terbaru</h3><div class="activity-list" id="activity"><span class="empty-activity" id="emptyActivity">Belum ada scan pada sesi ini.</span></div></section>
</main>
<div class="scan-popup" id="scanPopup" role="dialog" aria-modal="true" aria-labelledby="scanPopupTitle">
    <div class="scan-popup-card"><div class="popup-icon" id="scanPopupIcon"></div><h2 id="scanPopupTitle"></h2><p class="scan-popup-message" id="scanPopupMessage"></p><div class="popup-details" id="scanPopupDetails" hidden></div><button type="button" class="popup-close" id="scanPopupClose">TUTUP</button></div>
</div>
<script>
let locked=false;let scanning=false;let activeCamera=null;
function tick(){document.getElementById('clock').textContent=new Date().toLocaleTimeString('id-ID',{hour:'2-digit',minute:'2-digit',second:'2-digit'})}tick();setInterval(tick,1000);
function initials(name){return name.split(/\s+/).slice(0,2).map(x=>x[0]).join('').toUpperCase()}
function showResult(type,name,meta,message){const box=document.getElementById('resultBody');box.classList.remove('pulse');void box.offsetWidth;box.classList.add('pulse');box.innerHTML=`<div class="result-card ${type}"><div class="student-avatar">${type==='success'?initials(name):'<i class="bi bi-x-lg"></i>'}</div><h2>${name}</h2><div class="student-meta">${meta||''}</div><div class="result-badge"><i class="bi ${type==='success'?'bi-check-circle-fill':'bi-exclamation-circle-fill'}"></i>${message}</div></div>`}
const popup=document.getElementById('scanPopup');let popupTimer=null;
function safe(value){const node=document.createElement('span');node.textContent=value??'-';return node.innerHTML}
let audioContext=null;
function enableScanSound(){try{audioContext??=new(window.AudioContext||window.webkitAudioContext)();if(audioContext.state==='suspended')audioContext.resume()}catch(error){}}
document.addEventListener('pointerdown',enableScanSound,{once:true,capture:true});
function playScanSound(type){try{audioContext??=new(window.AudioContext||window.webkitAudioContext)();if(audioContext.state==='suspended')audioContext.resume();const patterns={success:[[660,0,.13],[880,.15,.2]],warning:[[520,0,.16],[520,.22,.16]],error:[[330,0,.18],[220,.2,.28]]};(patterns[type]||patterns.error).forEach(([frequency,delay,duration])=>{const oscillator=audioContext.createOscillator();const gain=audioContext.createGain();const start=audioContext.currentTime+delay;oscillator.type=type==='success'?'sine':'triangle';oscillator.frequency.setValueAtTime(frequency,start);gain.gain.setValueAtTime(.0001,start);gain.gain.exponentialRampToValueAtTime(.22,start+.02);gain.gain.exponentialRampToValueAtTime(.0001,start+duration);oscillator.connect(gain);gain.connect(audioContext.destination);oscillator.start(start);oscillator.stop(start+duration+.03)})}catch(error){/* Tampilan pop-up tetap bekerja jika audio diblokir browser. */}}
function speakScanResult(type,message,details){if(!('speechSynthesis'in window))return playScanSound(type);let text;if(type==='success'){text=`Absensi berhasil. ${details.Nama||''}, kelas ${details.Kelas||''}`;}else if(type==='warning'){text='Siswa sudah melakukan absensi hari ini.';}else if(/kelas/i.test(message)){text='Absensi ditolak. Siswa salah kelas.';}else{text='Scan gagal. Silakan coba kembali.';}window.speechSynthesis.cancel();const voice=new SpeechSynthesisUtterance(text);voice.lang='id-ID';voice.rate=.95;voice.pitch=1;voice.volume=1;window.speechSynthesis.speak(voice)}
function showPopup(type,title,message,details={}){clearTimeout(popupTimer);speakScanResult(type,message,details);popup.className=`scan-popup ${type} show`;document.getElementById('scanPopupIcon').innerHTML=`<i class="bi ${type==='success'?'bi-check-lg':type==='warning'?'bi-exclamation-lg':'bi-x-lg'}"></i>`;document.getElementById('scanPopupTitle').textContent=title;document.getElementById('scanPopupMessage').textContent=message;const detailBox=document.getElementById('scanPopupDetails');const rows=Object.entries(details);detailBox.hidden=!rows.length;detailBox.innerHTML=rows.map(([label,value])=>`<div class="popup-row"><span>${safe(label)}</span><strong>${safe(value)}</strong></div>`).join('');popupTimer=setTimeout(closePopup,4500)}
function closePopup(){clearTimeout(popupTimer);popup.classList.remove('show')}
