function scanned(token){const now=Date.now();if(locked||(scanCooldown.get(token)||0)>now)return;locked=true;scanCooldown.set(token,now+5000);fetch('{{route('attendance.scan.store')}}',{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-TOKEN':document.querySelector('meta[name=csrf-token]').content},body:JSON.stringify({token})}).then(async response=>{const data=await response.json();if(!response.ok)throw new Error(data.message||Object.values(data.errors||{})[0]?.[0]||'Scan gagal');const a=data.attendance;const student=a.student;const className=student.school_class?.class_name||'-';showResult('success',student.name,`${student.nis||'-'} · ${className}`,`${a.status} pukul ${a.check_in_time}`);showPopup('success','Absensi Berhasil',`Status: ${a.status} pukul ${a.check_in_time}`,{'Nama':student.name,'NIS/NISN':student.nis||'-','Kelas':className});document.getElementById('total').textContent=+document.getElementById('total').textContent+1;if(a.status==='hadir')document.getElementById('present').textContent=+document.getElementById('present').textContent+1;if(a.status==='terlambat')document.getElementById('late').textContent=+document.getElementById('late').textContent+1;document.getElementById('emptyActivity')?.remove();document.getElementById('activity').insertAdjacentHTML('afterbegin',`<div class="activity-item"><strong>${safe(student.name)}</strong><small>${safe(className)} · ${safe(a.status)} · ${safe(a.check_in_time)}</small></div>`);clearTimeout(resultTimer);resultTimer=setTimeout(()=>{document.getElementById('resultBody').innerHTML='<div class="result-empty"><i class="bi bi-person-bounding-box"></i><h2>Siap memindai siswa berikutnya</h2><p>Arahkan QR kartu pelajar ke kamera.</p></div>'},5000)}).catch(error=>{scanCooldown.delete(token);const message=error.message||'Scan gagal';const duplicate=/sudah melakukan absensi/i.test(message);const wrongClass=/bukan anggota kelas/i.test(message);showResult('error',duplicate?'Sudah Absen':wrongClass?'Salah Kelas':'Scan tidak berhasil','Silakan periksa kartu dan coba kembali',message);showPopup(duplicate?'warning':'error',duplicate?'Siswa Sudah Absen':wrongClass?'Siswa Salah Kelas':'Scan Gagal',message)}).finally(()=>{locked=false})}
const qrScanner=new Html5Qrcode('reader',{formatsToSupport:[Html5QrcodeSupportedFormats.QR_CODE],experimentalFeatures:{useBarCodeDetectorIfSupported:true},verbose:false});
function scannerBox(viewWidth,viewHeight){const available=Math.max(120,Math.min(viewWidth,viewHeight)-24);const size=Math.min(available,Math.max(160,Math.floor(Math.min(viewWidth,viewHeight)*.75)));return{width:size,height:size}}
function optimizeCameraFocus(){const track=document.querySelector('#reader video')?.srcObject?.getVideoTracks?.()[0];if(!track?.getCapabilities||!track?.applyConstraints)return;const capabilities=track.getCapabilities();const advanced=[];if(Array.isArray(capabilities.focusMode)&&capabilities.focusMode.includes('continuous'))advanced.push({focusMode:'continuous'});if(advanced.length)track.applyConstraints({advanced}).catch(()=>{})}
function startScanning(){if(scanning)return;const facingMode=document.getElementById('cameraFacing').value;const config={fps:15,qrbox:scannerBox,aspectRatio:1.15,disableFlip:facingMode==='environment'};const activate=()=>{scanning=true;activeCamera=facingMode;optimizeCameraFocus();document.querySelector('.camera-stage').classList.add('active');const button=document.getElementById('toggleScanner');button.textContent='HENTIKAN SCAN';button.classList.remove('off')};qrScanner.start({facingMode},config,scanned).then(activate).catch(firstError=>Html5Qrcode.getCameras().then(cameras=>{if(!cameras.length)throw firstError;const pattern=facingMode==='environment'?/back|rear|environment|belakang/i:/front|user|depan|facetime/i;const camera=cameras.find(item=>pattern.test(item.label))||(facingMode==='environment'?cameras[cameras.length-1]:cameras[0]);return qrScanner.start(camera.id,config,scanned).then(activate)}).catch(error=>{console.error('Gagal membuka kamera:',error);const insecure=!window.isSecureContext;document.getElementById('reader').innerHTML=`<div class="camera-placeholder"><i class="bi bi-camera-video-off"></i><strong>Kamera tidak dapat dibuka</strong><small>${insecure?'Kamera memerlukan akses melalui HTTPS':'Periksa izin kamera di Safari, lalu muat ulang halaman'}</small></div>`}))}
function stopScanning(){if(!scanning)return Promise.resolve();return qrScanner.stop().then(()=>{scanning=false;const button=document.getElementById('toggleScanner');button.textContent='MULAI SCAN';button.classList.add('off');document.querySelector('.camera-stage').classList.remove('active')})}
document.getElementById('cameraFacing').addEventListener('change',()=>{if(scanning)stopScanning().then(startScanning).catch(()=>{})});document.getElementById('qrImageInput').addEventListener('change',event=>{const file=event.target.files?.[0];if(!file)return;qrScanner.scanFile(file,true).then(scanned).catch(()=>showResult('error','QR tidak terbaca','Pilih gambar kartu dengan QR yang jelas','Gambar QR tidak valid'));event.target.value='' });document.getElementById('toggleScanner').addEventListener('click',()=>{if(scanning){stopScanning().then(()=>{document.getElementById('reader').innerHTML='<div class="camera-placeholder"><i class="bi bi-phone"></i><strong>Siap memindai kartu siswa</strong><button type="button" class="request-camera" onclick="document.getElementById(\'toggleScanner\').click()">Izinkan Kamera</button><label class="image-scan-link" for="qrImageInput">Scan dari gambar</label></div>'}).catch(()=>{})}else startScanning()});</script>
</body></html>





